#include <Arduino.h>
#include <WiFi.h>
#include <HTTPClient.h>
#include <WiFiManager.h>

// ============================================================================
// WYMUSZENIE KONFIGURACJI WYŚWIETLACZA LILYGO T-EMBED (ST7789)
// ============================================================================
#define USER_SETUP_LOADED 1
#define ST7789_DRIVER     1
#define TFT_WIDTH         170
#define TFT_HEIGHT        320
#define TFT_MOSI          9
#define TFT_SCLK          10
#define TFT_CS            41
#define TFT_DC            16
#define TFT_RST           -1
#define LOAD_GLCD         1  // Załadowanie podstawowej czcionki
#define SPI_FREQUENCY     27000000
#include <TFT_eSPI.h>

#define PIN_POWER_ON      15 
#define PIN_LCD_BL        21 

TFT_eSPI tft = TFT_eSPI();

// Surowa ramka testowa (niezaszyfrowana)
String rawTelegramHEX = "2E44A2111003451234567810070E2F0000000C13453211000C1400000000"; 

struct MeterData {
    String id = "N/A";
    String serial = "N/A";
    String usage = "N/A";
};

// Bezpieczna funkcja pobierania danych z wmbusmeters.org
MeterData analyzeTelegramOnline(String hexFrame) {
    MeterData data;
    if (WiFi.status() != WL_CONNECTED) return data;

    HTTPClient http;
    http.begin("https://wmbusmeters.org");
    http.addHeader("Content-Type", "application/x-www-form-urlencoded");
    http.addHeader("User-Agent", "Mozilla/5.0 (ESP32; SmartMeter)"); 

    hexFrame.toUpperCase();
    String postData = "telegram=" + hexFrame + "&driver=auto&key=";

    int httpResponseCode = http.POST(postData);

    if (httpResponseCode == 200) {
        String response = http.getString();

        int idPos = response.indexOf("id:");
        if (idPos != -1) {
            int endLine = response.indexOf("\n", idPos);
            data.id = response.substring(idPos + 3, endLine);
            data.id.trim();
        }
        int serialPos = response.indexOf("serial:");
        if (serialPos != -1) {
            int endLine = response.indexOf("\n", serialPos);
            data.serial = response.substring(serialPos + 7, endLine);
            data.serial.trim();
        }
        int totalPos = response.indexOf("total_water_m3:");
        if (totalPos != -1) {
            int endLine = response.indexOf("\n", totalPos);
            data.usage = response.substring(totalPos + 15, endLine) + " m3";
            data.usage.trim();
        } else {
            int usagePos = response.indexOf("usage:");
            if (usagePos != -1) {
                int endLine = response.indexOf("\n", usagePos);
                data.usage = response.substring(usagePos + 6, endLine);
                data.usage.trim();
            }
        }
    }
    http.end();
    return data;
}

// POPRAWKA: Usunięcie problematycznego tft.textWidth() i zastąpienie stałymi X
void updateScreen(String status, MeterData meter) {
    tft.fillScreen(TFT_BLACK);
    tft.drawRect(0, 0, tft.width(), tft.height(), TFT_CYAN);

    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextSize(2);
    tft.setCursor(15, 15);
    tft.print("WMBUS DECODER ONLINE");

    tft.setTextSize(1);
    tft.setTextColor(TFT_YELLOW, TFT_BLACK);
    tft.setCursor(15, 45);
    tft.print("Status: " + status);

    tft.setTextSize(2);
    tft.setTextColor(TFT_GREEN, TFT_BLACK);
    tft.setCursor(15, 70);
    tft.print("ID: " + meter.id);

    tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
    tft.setCursor(15, 100);
    tft.print("SERIAL: " + meter.serial);

    tft.setTextColor(TFT_ORANGE, TFT_BLACK);
    tft.setCursor(15, 130);
    tft.print("ODCZYT: " + meter.usage);
}

void setup() {
    Serial.begin(115200);
    delay(1000); 

    // Gwarantowane sekwencyjne włączenie ekranu
    pinMode(PIN_POWER_ON, OUTPUT);
    digitalWrite(PIN_POWER_ON, HIGH);

    pinMode(PIN_LCD_BL, OUTPUT);
    digitalWrite(PIN_LCD_BL, LOW); 
    delay(500);

    tft.init();
    tft.setRotation(3); 
    tft.fillScreen(TFT_BLACK); 

    digitalWrite(PIN_LCD_BL, HIGH); 
    delay(100);

    // Wyświetlenie komunikatu o starcie sieci bez używania textWidth
    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextSize(2);
    tft.setCursor(15, 30);
    tft.println("Menu Wi-Fi Aktywne");
    tft.setTextSize(1);
    tft.setCursor(15, 65);
    tft.println("Polacz sie z siecia: T-Embed-WiFi");
    tft.setCursor(15, 85);
    tft.println("aby wprowadzic haslo internetu.");

    WiFiManager wm;
    // Zmniejszamy czas oczekiwania na połączenie do 2 minut (120s), żeby nie blokować kodu w nieskończoność
    wm.setConfigPortalTimeout(120);

    if (!wm.autoConnect("T-Embed-WiFi")) {
        Serial.println("Timeout portalu Wi-Fi. Praca bez sieci...");
    } else {
        Serial.println("Polaczono z Wi-Fi!");
    }

    MeterData startData;
    updateScreen("Polaczono! Oczekiwanie...", startData);
}

void loop() {
    updateScreen("Wysylanie do wmbusmeters...", MeterData());

    // Testowe dekodowanie
    MeterData result = analyzeTelegramOnline(rawTelegramHEX);

    updateScreen("Gotowe!", result);

    delay(20000); // Odświeżanie co 20 sekund
}
